import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Architecture & Design Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),n={name:"guide/architecture.md"};function r(o,e,c,l,d,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="architecture-design-overview" tabindex="-1">Architecture &amp; Design Overview <a class="header-anchor" href="#architecture-design-overview" aria-label="Permalink to &quot;Architecture &amp; Design Overview&quot;">​</a></h1><p>FOSSBilling is built upon the <strong>Domain-Driven Clean Architecture</strong> and <strong>SOLID</strong> principles, ensuring that business rules remain completely decoupled from transport layers, databases, and third-party APIs.</p><hr><h2 id="🏗️-layered-clean-architecture" tabindex="-1">🏗️ Layered Clean Architecture <a class="header-anchor" href="#🏗️-layered-clean-architecture" aria-label="Permalink to &quot;🏗️ Layered Clean Architecture&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>├── core/</span></span>
<span class="line"><span>│   ├── domain/        # Core business entities &amp; repository interfaces (Pure Go)</span></span>
<span class="line"><span>│   ├── usecase/       # Application business use cases (Invoice, Cart, Auth, Staff...)</span></span>
<span class="line"><span>│   ├── repository/    # Persistence implementation (PostgreSQL &amp; Memory Mock)</span></span>
<span class="line"><span>│   ├── service/       # Provisioners (cPanel, Plesk...), Payment Gateways, Notifications</span></span>
<span class="line"><span>│   ├── listener/      # Event-driven subscribers (Event Bus)</span></span>
<span class="line"><span>│   └── handler/       # Presentation layer (HTTP REST handlers &amp; JSON responses)</span></span>
<span class="line"><span>├── pkg/               # Reusable utility libraries (Auth, Decimal Money, PDF, Mailer, i18n)</span></span>
<span class="line"><span>└── cmd/               # Executable entrypoints (api, worker, cli, demo)</span></span></code></pre></div><hr><h2 id="🎯-design-patterns-used" tabindex="-1">🎯 Design Patterns Used <a class="header-anchor" href="#🎯-design-patterns-used" aria-label="Permalink to &quot;🎯 Design Patterns Used&quot;">​</a></h2><h3 id="_1-fluent-entity-builders" tabindex="-1">1. Fluent Entity Builders <a class="header-anchor" href="#_1-fluent-entity-builders" aria-label="Permalink to &quot;1. Fluent Entity Builders&quot;">​</a></h3><p>Complex business entities use type-safe builders:</p><ul><li><strong><code>InvoiceBuilder</code></strong>: Builds immutable invoices with auto-calculated subtotals, compound/flat tax rates, line items, and dynamic currency conversions.</li><li><strong><code>ClientBuilder</code></strong>: Validates credentials, sets default currency, creates default client balance, and hashes passwords securely.</li><li><strong><code>OrderBuilder</code></strong>: Manages billing cycle periods, renewals, and custom form configuration values.</li></ul><h3 id="_2-dynamic-gateway-provisioner-factories" tabindex="-1">2. Dynamic Gateway &amp; Provisioner Factories <a class="header-anchor" href="#_2-dynamic-gateway-provisioner-factories" aria-label="Permalink to &quot;2. Dynamic Gateway &amp; Provisioner Factories&quot;">​</a></h3><ul><li><strong><code>PaymentGatewayFactory</code></strong>: Instantiates and executes gateways dynamically based on payment method (<code>midtrans</code>, <code>stripe</code>, <code>paypal</code>, <code>bank_transfer</code>, <code>custom</code>).</li><li><strong><code>ProvisionerFactory</code></strong>: Directs service creation, suspension, unsuspension, and password updates across hosting control panels (<code>cpanel</code>, <code>plesk</code>, <code>directadmin</code>, <code>hestia</code>, <code>cwp</code>, <code>custom</code>).</li></ul><h3 id="_3-decoupled-event-bus" tabindex="-1">3. Decoupled Event Bus <a class="header-anchor" href="#_3-decoupled-event-bus" aria-label="Permalink to &quot;3. Decoupled Event Bus&quot;">​</a></h3><p>The asynchronous <code>EventBus</code> publishes domain events without coupling producers to consumers:</p><ul><li><code>client.created</code> ➔ Dispatches welcome email template &amp; initializes client balance.</li><li><code>invoice.paid</code> ➔ Triggers automatic order provisioning &amp; receipt generation.</li><li><code>order.activated</code> ➔ Dispatches login details to the customer.</li></ul><h3 id="_4-zero-loss-decimal-money-arithmetic" tabindex="-1">4. Zero-Loss Decimal Money Arithmetic <a class="header-anchor" href="#_4-zero-loss-decimal-money-arithmetic" aria-label="Permalink to &quot;4. Zero-Loss Decimal Money Arithmetic&quot;">​</a></h3><p>All monetary calculations throughout the system use the <code>decimal.Money</code> fixed-point arithmetic package (<code>pkg/decimal</code>), preventing floating-point precision rounding errors common in billing platforms.</p>`,17)])])}const m=a(n,[["render",r]]);export{h as __pageData,m as default};
